import 'package:flutter_test/flutter_test.dart';
import 'package:mobile_flutter/services/offline_read_log.dart';
import 'package:mobile_flutter/services/tag_crypto.dart';

// Vectors generated by backend/app/tag_crypto.py with
// SECRET_KEY="vector-secret", key_id=1 -- this test is what pins the Dart
// reader to the Python sealer / hash-chain wire format.
const _uid = '04A1B2C3D4E5F6';
const _blob =
    'C1.1.eHAK2y0YG-gQSTII7ABXuypXwzAcDJ5IDUzksI3nn28TsNhBwJbZIvWdGZjoMfUaKpeecjs0HA';
const _key = '6x/M7sTsAzdKH/P8wl9ne3mPVDpJ2ZfqHadS9mhywSQ=';
const _chainHash = 'a4ec4bd83ce236ee551a3f81569902b6be0cb133e4e3e06de55d19179d538aa6';

void main() {
  test('opens a blob sealed by the backend', () async {
    expect(await TagCrypto.open(_blob, _uid, {'1': _key}), 'BT:O+|AL:Penicillin(severe)');
  });

  test('refuses a blob copied to a different tag', () async {
    expect(await TagCrypto.open(_blob, '04FFFFFFFFFFFF', {'1': _key}), isNull);
  });

  test('refuses when the key is not cached or the blob is tampered', () async {
    expect(await TagCrypto.open(_blob, _uid, {}), isNull);
    final tampered = '${_blob.substring(0, _blob.length - 2)}AA';
    expect(await TagCrypto.open(tampered, _uid, {'1': _key}), isNull);
  });

  test('sealed vs legacy plaintext detection', () {
    expect(TagCrypto.looksSealed(_blob), isTrue);
    expect(TagCrypto.looksSealed('BT:O+|AL:Penicillin(severe)'), isFalse);
    expect(TagCrypto.keyIdOf(_blob), 1);
  });

  test('offline-read chain hash matches the backend', () async {
    final h = await OfflineReadLog.entryHash(
      OfflineReadLog.genesisHash, 0, '2026-10-10T08:00:00.000Z', _uid, 1, 'decrypted',
    );
    expect(h, _chainHash);
  });
}
